    33  bool smtp_server_cmd_data_check_size(struct smtp_server_cmd_ctx *cmd)
    34  {
    35          struct smtp_server_connection *conn = cmd->conn;
    36          const struct smtp_server_settings *set = &conn->set;
    37
    38          i_assert(conn->state.state == SMTP_SERVER_STATE_DATA);
    39
    40          if (conn->state.data_input == NULL)
    41                  return TRUE;
    42          if (set->max_message_size == 0)
    43                  return TRUE;
    44          if (conn->state.data_input->v_offset <= set->max_message_size)
    45                  return TRUE;
    46
    47          smtp_server_cmd_data_size_limit_exceeded(cmd);
    48          return FALSE;
    49  }
