    51  bool smtp_server_connection_data_check_state(struct smtp_server_cmd_ctx *cmd)
    52  {
    53          struct smtp_server_connection *conn = cmd->conn;
    54          struct smtp_server_command *command = cmd->cmd;
    55          struct cmd_data_context *data_cmd = command->data;
    56
    57          if (conn->state.data_chunks > 0 && conn->state.data_failed) {
    58                  // FIXME: should it even reply anything? RFC is unclear.
    59                  smtp_server_command_fail(command, 503, "5.5.0",
    60                          "Previous data chunk failed, issue RSET first");
    61                  return FALSE;
    62          }
    63
    64          /* check valid MAIL */
    65          if (conn->state.trans == NULL
    66                  && conn->state.pending_mail_cmds == 0) {
    67                  smtp_server_command_fail(command,
    68                          503, "5.5.0", "MAIL needed first");
    69                  return FALSE;
    70          }
    71          if (conn->state.trans != NULL &&
    72              (conn->state.trans->params.body.type ==
    73                  SMTP_PARAM_MAIL_BODY_TYPE_BINARYMIME) &&
    74              !data_cmd->chunking) {
    75                  /* RFC 3030, Section 3:
    76                     BINARYMIME cannot be used with the DATA command. If a DATA
    77                     command is issued after a MAIL command containing the
    78                     body-value of "BINARYMIME", a 503 "Bad sequence of commands"
    79                     response MUST be sent. The resulting state from this error
    80                     condition is indeterminate and the transaction MUST be reset
    81                     with the RSET command. */
    82                  smtp_server_command_fail(command,
    83                          503, "5.5.0", "DATA cannot be used with BINARYMIME");
    84                  return FALSE;
    85          }
    86
    87          /* Can only decide whether we have valid recipients once there are no
    88             pending RCPT commands */
    89          if (conn->state.pending_rcpt_cmds > 0)
    90                  return TRUE;
    91
    92          /* special handling for LMTP */
    93          if (conn->set.protocol == SMTP_PROTOCOL_LMTP) {
    94                  /* check valid RCPT (at least one) */
    95                  if (conn->state.trans == NULL ||
    96                      !smtp_server_transaction_has_rcpt(conn->state.trans)) {
    97                          if (data_cmd->chunk_size > 0 && data_cmd->chunk_last) {
    98                                  /* RFC 2033, Section 4.3:
    99                                     If there were no previously successful RCPT
   100                                     commands in the mail transaction, then the
   101                                     BDAT LAST command returns zero replies.
   102                                   */
   103                                  smtp_server_command_abort(&command);
   104                          } else {
   105                                  /* RFC 2033, Section 4.2:
   106                                     The additional restriction is that when there
   107                                     have been no successful RCPT commands in the
   108                                     mail transaction, the DATA command MUST fail
   109                                     with a 503 reply code.
   110                                  */
   111                                  smtp_server_command_fail(command,
   112                                          503, "5.5.0", "No valid recipients");
   113                          }
   114                          return FALSE;
   115                  }
   116
   117          } else {
   118                  /* check valid RCPT (at least one) */
   119                  if (conn->state.trans == NULL ||
   120                          !smtp_server_transaction_has_rcpt(conn->state.trans)) {
   121                          smtp_server_command_fail(command,
   122                                  554, "5.5.0", "No valid recipients");
   123                          return FALSE;
   124                  }
   125          }
   126          return TRUE;
   127  }
