   338  static void
   339  cmd_data_next(struct smtp_server_cmd_ctx *cmd,
   340                struct cmd_data_context *data_cmd)
   341  {
   342          struct smtp_server_connection *conn = cmd->conn;
   343          struct smtp_server_transaction *trans = conn->state.trans;
   344          const struct smtp_server_callbacks *callbacks = conn->callbacks;
   345          struct smtp_server_command *command = cmd->cmd;
   346
   347          /* this command is next to send a reply */
   348
   349          i_assert(data_cmd != NULL);
   350          i_assert(trans != NULL);
   351          i_assert(conn->state.pending_mail_cmds == 0 &&
   352                  conn->state.pending_rcpt_cmds == 0);
   353          i_assert(trans != NULL);
   354
   355          e_debug(cmd->event, "Command is next to be replied");
   356
   357          /* check whether we have had successful mail and rcpt commands */
   358          if (!smtp_server_connection_data_check_state(cmd))
   359                  return;
   360
   361          if (data_cmd->chunk_last) {
   362                  /* This is the last chunk */
   363                  smtp_server_transaction_last_data(trans, cmd);
   364
   365                  /* LMTP 'DATA' and 'BDAT LAST' commands need to send more than
   366                     one reply per recipient */
   367                  if (HAS_ALL_BITS(trans->flags,
   368                                   SMTP_SERVER_TRANSACTION_FLAG_REPLY_PER_RCPT)) {
   369                          smtp_server_command_set_reply_count(command,
   370                                  array_count(&trans->rcpt_to));
   371                  }
   372          }
   373
   374          smtp_server_connection_set_state(conn, SMTP_SERVER_STATE_DATA, NULL);
   375
   376          /* chain data streams in the correct order */
   377          if (conn->state.data_chain != NULL) {
   378                  i_assert(data_cmd->chunk_input != NULL);
   379                  i_stream_chain_append(conn->state.data_chain,
   380                                        data_cmd->chunk_input);
   381                  if (data_cmd->chunk_last) {
   382                          e_debug(cmd->event, "Seen the last chunk");
   383                          i_stream_chain_append_eof(conn->state.data_chain);
   384                  }
   385          }
   386
   387          if (data_cmd->chunk_first) {
   388                  struct smtp_server_command *cmd_temp = command;
   389
   390                  e_debug(cmd->event, "First chunk");
   391
   392                  smtp_server_command_ref(cmd_temp);
   393                  i_assert(callbacks != NULL &&
   394                           callbacks->conn_cmd_data_begin != NULL);
   395                  if (callbacks->conn_cmd_data_begin(conn->context,
   396                          cmd, conn->state.trans, conn->state.data_input) < 0) {
   397                          i_assert(smtp_server_command_is_replied(cmd_temp));
   398                          /* command failed */
   399                          smtp_server_command_unref(&cmd_temp);
   400                          return;
   401                  }
   402                  if (!smtp_server_command_unref(&cmd_temp))
   403                          return;
   404          }
   405
   406          if (smtp_server_command_is_replied(command)) {
   407                  smtp_server_command_input_unlock(cmd);
   408          } else {
   409                  if (data_cmd->client_input) {
   410                          /* using input from client connection;
   411                             capture I/O event */
   412                          smtp_server_connection_timeout_start(conn);
   413                          smtp_server_command_input_capture(cmd, cmd_data_input);
   414                  }
   415
   416                  (void)cmd_data_handle_input(cmd);
   417          }
   418  }
