   497  void smtp_server_cmd_data(struct smtp_server_cmd_ctx *cmd,
   498                            const char *params)
   499  {
   500          struct smtp_server_connection *conn = cmd->conn;
   501          struct smtp_server_command *command = cmd->cmd;
   502          struct cmd_data_context *data_cmd;
   503
   504          /* data = "DATA" CRLF */
   505          if (*params != '\0') {
   506                  smtp_server_reply(cmd,
   507                          501, "5.5.4", "Invalid parameters");
   508                  return;
   509          }
   510
   511          smtp_server_command_input_lock(cmd);
   512
   513          data_cmd = p_new(cmd->pool, struct cmd_data_context, 1);
   514          data_cmd->chunk_first = TRUE;
   515          data_cmd->chunk_last = TRUE;
   516          data_cmd->client_input = TRUE;
   517          command->data = data_cmd;
   518
   519          smtp_server_command_add_hook(command, SMTP_SERVER_COMMAND_HOOK_NEXT,
   520                                       cmd_data_start, data_cmd);
   521          smtp_server_command_add_hook(command, SMTP_SERVER_COMMAND_HOOK_REPLIED_ONE,
   522                                       cmd_data_replied_one, data_cmd);
   523          smtp_server_command_add_hook(command, SMTP_SERVER_COMMAND_HOOK_REPLIED,
   524                                       cmd_data_replied, data_cmd);
   525          smtp_server_command_add_hook(command, SMTP_SERVER_COMMAND_HOOK_DESTROY,
   526                                       cmd_data_destroy, data_cmd);
   527
   528          conn->state.pending_data_cmds++;
   529  }
