   559  int smtp_server_connection_data_chunk_add(struct smtp_server_cmd_ctx *cmd,
   560          struct istream *chunk, uoff_t chunk_size, bool chunk_last,
   561          bool client_input)
   562  {
   563          struct smtp_server_connection *conn = cmd->conn;
   564          const struct smtp_server_settings *set = &conn->set;
   565          struct smtp_server_command *command = cmd->cmd;
   566          struct cmd_data_context *data_cmd = command->data;
   567          uoff_t new_size;
   568
   569          i_assert(data_cmd != NULL);
   570
   571          if (!smtp_server_connection_data_check_state(cmd))
   572                  return -1;
   573
   574          /* check message size increase early */
   575          new_size = conn->state.data_size + chunk_size;
   576          if (new_size < conn->state.data_size ||
   577              (set->max_message_size > 0 && new_size > set->max_message_size)) {
   578                  smtp_server_cmd_data_size_limit_exceeded(cmd);
   579                  return -1;
   580          }
   581          conn->state.data_size = new_size;
   582
   583          if (chunk_last) {
   584                  smtp_server_command_remove_hook(
   585                          command, SMTP_SERVER_COMMAND_HOOK_REPLIED,
   586                          cmd_data_chunk_replied);
   587                  smtp_server_command_add_hook(
   588                          command, SMTP_SERVER_COMMAND_HOOK_REPLIED,
   589                          cmd_data_replied, data_cmd);
   590          }
   591
   592          data_cmd->chunk_input = chunk;
   593          data_cmd->chunk_size = chunk_size;
   594          data_cmd->chunk_last = chunk_last;
   595          data_cmd->client_input = client_input;
   596          i_stream_ref(chunk);
   597
   598          cmd_data_start_input(cmd, data_cmd, conn->state.data_chain_input);
   599          i_stream_unref(&conn->state.data_chain_input);
   600          return 0;
   601  }
