   603  /* BDAT command */
   604
   605  void smtp_server_cmd_bdat(struct smtp_server_cmd_ctx *cmd,
   606                            const char *params)
   607  {
   608          struct smtp_server_connection *conn = cmd->conn;
   609          struct istream *input = NULL;
   610          uoff_t size = 0;
   611          const char *const *argv;
   612          bool chunk_last = FALSE;
   613          int ret = 1;
   614
   615          if ((conn->set.capabilities & SMTP_CAPABILITY_CHUNKING) == 0) {
   616                  smtp_server_reply(cmd,
   617                          502, "5.5.1", "Unsupported command");
   618                  return;
   619          }
   620
   621          smtp_server_connection_data_chunk_init(cmd);
   622
   623          /* bdat-cmd   = "BDAT" SP chunk-size [ SP end-marker ] CR LF
   624             chunk-size = 1*DIGIT
   625             end-marker = "LAST"
   626           */
   627          argv = t_strsplit(params, " ");
   628          if (argv[0] == NULL || str_to_uoff(argv[0], &size) < 0) {
   629                  smtp_server_reply(cmd,
   630                          501, "5.5.4", "Invalid chunk size parameter");
   631                  size = 0;
   632                  ret = -1;
   633          } else if (argv[1] != NULL) {
   634                  if (argv[2] != NULL) {
   635                          smtp_server_reply(cmd,
   636                                  501, "5.5.4", "Invalid parameters");
   637                          ret = -1;
   638                  } else if (strcasecmp(argv[1], "LAST") != 0) {
   639                          smtp_server_reply(cmd,
   640                                  501, "5.5.4", "Invalid end marker parameter");
   641                          ret = -1;
   642                  } else {
   643                          chunk_last = TRUE;
   644                  }
   645          }
   646
   647          if (ret > 0 || (size > 0 && !conn->disconnected)) {
   648                  /* Read/skip data even in case of error, as long as size is
   649                     known and connection is still usable. */
   650                  input = smtp_command_parse_data_with_size(conn->smtp_parser,
   651                                                            size);
   652          }
   653
   654          if (ret < 0) {
   655                  i_stream_unref(&input);
   656                  return;
   657          }
   658
   659          (void)smtp_server_connection_data_chunk_add(cmd,
   660                  input, size, chunk_last, TRUE);
   661          i_stream_unref(&input);
   662  }
